write('/guides/','Packaging Guides for B2B Buyers | PackHubGlobe','Prepare a packaging quote brief and compare box and pouch structures with practical buyer guides.',intro('The packaging notebook','Make the next<br>packaging decision clearer.','Practical starting guides for buyers, brand teams and sourcing managers. Use them to define the questions your sample and specification need to answer.')+'<section class="section wrap" style="padding-top:0">'+guides()+'</section>'+cta())
for slug,label,title,desc,sections in GUIDES:
 body=intro(label,title,desc,'<a href="/guides/">Guides</a> / '+label)+'<article class="article wrap">'
 body+=''.join(f'<h2>{a}</h2><p>{b}</p>' for a,b in sections)
 body+='<h2>Turn the decision into a brief.</h2><p>Share your product, quantity, dimensions or fill weight, artwork status and destination. <a href="/request-quote/">Prepare your packaging request</a> or <a href="/products/">compare packaging categories</a>.</p></article>'+cta()
 write('/guides/'+slug+'/',title+' | PackHubGlobe',desc,body)

body=intro('About','About PackHubGlobe.','Paper packaging, flexible packaging and printed details, brought together for business buyers.')+'<section class="wrap section" style="padding-top:0"><div class="split"><figure class="scene"><img src="/assets/factory/offset-printing.png" alt="Offset press at the paper packaging facility" width="780" height="439" loading="lazy"><figcaption>Paper packaging production</figcaption></figure><div><h2>One conversation.<br>The right packaging range.</h2><p>Plan boxes, bags, pouches, cards and labels around your product. Share your quantity, artwork and delivery market to start with the decisions that matter.</p><a class="textlink" href="/factory/">Explore our production capabilities</a></div></div><div class="two about-companies"><section><h2>Paper packaging</h2><h3>Xiamen Finer Packaging Co., Ltd.</h3><p>Paper packaging projects are represented by Xiamen Finer Packaging Co., Ltd., with an existing range of folding cartons, rigid boxes and mailers.</p><a class="textlink" href="https://www.finerpack.com/about" target="_blank" rel="noopener noreferrer">Finer Pack company profile</a></section><section><h2>Flexible packaging</h2><h3>Xiamen Unique Packaging Technology Co., Ltd.</h3><p>Flexible packaging projects are represented by Xiamen Unique Packaging Technology Co., Ltd., covering custom printed pouches and flexible packaging applications.</p><a class="textlink" href="https://uniquepouches.com/about.html" target="_blank" rel="noopener noreferrer">Unique Packaging company profile</a></section></div><p class="smallnote">All enquiries go to '+EMAIL+'. Your quotation identifies the supplying company and agreed specification.</p></section>'+cta()
write('/about/','About PackHubGlobe | Paper & Flexible Packaging','Discover the paper and flexible packaging companies behind the PackHubGlobe brand and its shared enquiry contact.',body)
body=intro('Factory','A closer look at production.','Explore paper packaging equipment, a flexible packaging production excerpt and the documents relevant to your order.')+'<section class="wrap section" style="padding-top:0"><div class="sectionhead"><div><h2>Paper packaging</h2><p>Xiamen Finer Packaging Co., Ltd.</p></div></div><div class="factory-gallery">'
for image,title,width,height in [('offset-printing','Offset printing',780,439),('die-cutting','Die cutting',566,434),('folder-gluer','Folding & gluing',934,525),('foil-stamping','Foil stamping',987,564)]:
 body+='<figure><a href="/assets/factory/'+image+'.png" target="_blank" rel="noopener noreferrer"><img src="/assets/factory/'+image+'.png" alt="'+title+' equipment at the paper packaging facility" width="'+str(width)+'" height="'+str(height)+'" loading="lazy"></a><figcaption>'+title+'</figcaption></figure>'
body+='</div></section><section class="section softbg"><div class="wrap split"><div><h2>Flexible packaging</h2><p>Xiamen Unique Packaging Technology Co., Ltd.</p><p>See a short excerpt showing flexible packaging equipment and production. For your order, discuss the material structure, print, closures and sample checks.</p><a class="textlink" href="https://uniquepouches.com/factory-tour.html" target="_blank" rel="noopener noreferrer">Explore the Unique Packaging factory tour</a></div><figure class="factory-film"><video controls playsinline preload="none" poster="/assets/media/factory-banner-poster.jpg" aria-label="Flexible packaging production excerpt"><source src="/assets/media/factory-banner.mp4" type="video/mp4"><a href="/assets/media/factory-banner.mp4">Open the production video</a></video><figcaption>Flexible packaging production excerpt · 18 seconds</figcaption></figure></div></section><section class="section wrap"><div class="certificate-layout"><a href="/assets/documents/finer-packaging-fsc-coc.pdf" target="_blank" rel="noopener noreferrer"><img src="/assets/documents/finer-packaging-fsc-coc.png" alt="Supplied FSC chain-of-custody document for Xiamen Finer Packaging Co., Ltd." width="849" height="1200" loading="lazy"></a><div><span class="eyebrow">Paper packaging documentation</span><h2>Review the document behind the claim.</h2><p>The supplied FSC chain-of-custody document names Xiamen Finer Packaging Co., Ltd.</p><dl class="certificate-facts"><dt>Certificate code</dt><dd>ESTS-COC-200302</dd><dt>Issue date shown</dt><dd>27 November 2025</dd><dt>Valid-until date shown</dt><dd>26 November 2030</dd></dl><p>Check the current certificate record. For an FSC-labelled order, confirm that the relevant claim appears on the quotation and delivery documents.</p><div class="actions"><a class="textlink" href="/assets/documents/finer-packaging-fsc-coc.pdf" target="_blank" rel="noopener noreferrer">View supplied PDF</a><a class="textlink" href="https://info.fsc.org/" target="_blank" rel="noopener noreferrer">Check certificate record</a></div></div></div></section>'+cta()
write('/factory/','Factory & Packaging Capabilities | PackHubGlobe','Review paper and flexible packaging responsibilities, production steps and evidence requirements.',body)

body=intro('Contact','Let’s talk packaging.','Tell us what you’re packing and the quantity you need. Still exploring? Approximate details are fine.')+'<section class="wrap section quotegrid" style="padding-top:0"><div><form id="quote-form"><div class="formgrid">'
for name,label,type_,required in [('name','Your name *','text',True),('email','Business email *','email',True)]:
 body+=f'<div class="field"><label for="{name}">{label}</label><input id="{name}" name="{name}" type="{type_}" required autocomplete="{name}" maxlength="180"></div>'
body+='<div class="field"><label for="product">Packaging type *</label><select id="product" name="product" required><option value="">Choose a product</option>'+''.join('<option>'+c['name']+'</option>' for c in CATEGORIES)+'<option>Multiple packaging products</option><option>Not sure yet</option></select></div><div class="field"><label for="quantity">Quantity per design *</label><input id="quantity" name="quantity" required maxlength="180" placeholder="e.g. 5,000 per design"></div><div class="field full"><label for="country">Delivery country / region *</label><input id="country" name="country" required autocomplete="country-name" maxlength="180"></div><div class="field full"><label for="details">Tell us about your project</label><textarea id="details" name="details" rows="4" maxlength="5000" placeholder="Product, approximate size, print ideas or any questions."></textarea></div></div><details class="optional-fields"><summary>Add company, dimensions or timing (optional)</summary><div class="formgrid"><div class="field full"><label for="company">Company / brand</label><input id="company" name="company" autocomplete="organization" maxlength="180"></div><div class="field"><label for="size">Size or fill weight</label><input id="size" name="size" maxlength="180"></div><div class="field"><label for="unit">Dimension unit</label><select id="unit" name="unit"><option>Not decided</option><option>mm</option><option>cm</option><option>inches</option></select></div><div class="field full"><label for="timing">Target delivery window</label><input id="timing" name="timing" maxlength="180"></div></div></details><label class="check"><input name="consent" type="checkbox" required><span>I understand this prepares an email draft. I’ll send it from my email app. <a href="/privacy/">Privacy</a></span></label><div class="actions"><button class="button" type="submit">Prepare email enquiry</button><button class="textbutton" type="button" id="download-brief">Download brief instead</button></div><div id="form-result" class="status" role="status" hidden><strong>Your draft is ready. It has not been sent.</strong><p>Open and send it from your email app. Add artwork or reference files there.</p><a class="textlink" id="email-draft" href="mailto:'+EMAIL+'">Open email draft</a></div></form></div><aside class="quoteaside"><h2>Prefer a conversation?</h2><p>Email your ideas or send us a message on WhatsApp.</p><a class="email" href="mailto:'+EMAIL+'">'+EMAIL+'</a>'+whatsapp('whatsapp-link')+'<p class="smallnote">+86 15105916426</p><p class="smallnote">Pricing, MOQ, samples and delivery are confirmed for your project.</p></aside></section>'
write('/request-quote/','Request a Custom Packaging Quote | PackHubGlobe','Prepare a brief for boxes, bags, pouches, cards and labels. Contact '+EMAIL+' with your product, quantity and destination.',body)
write('/privacy/','Privacy Information — Design Preview | PackHubGlobe','Understand how this frontend preview handles your packaging enquiry details.',intro('Privacy','Your brief stays in your browser.','This design preview does not include a form-submission server or analytics tracking.')+'<article class="article wrap"><h2>What happens to form information?</h2><p>The form prepares an email link or a text file locally in your browser. Clicking the email-draft link passes the entered brief to your selected email application, addressed to '+EMAIL+'. It does not send the email automatically. The download creates a local copy of the same brief.</p><h2>External resources</h2><p>The preview loads fonts from Google Fonts. External company-reference links are shown only on the About and Factory pages. No visitor analytics or marketing cookies are intentionally installed in this prototype.</p><h2>Before a public launch</h2><p>A complete public privacy notice must identify the responsible controller, enquiry processing, service providers, retention, international transfers and relevant rights. That notice and a secure server delivery endpoint are launch requirements.</p></article>')

